def transform(grid):
    # For each location in the 4x4 panels, output the most common
    # non-background color, with background when none is present.
    out = []
    for r in range(4):
        row = []
        for c in range(4):
            vals = [grid[r][p * 5 + c] for p in range(4)]
            vals = [v for v in vals if v != 0]
            if not vals:
                row.append(0)
            else:
                row.append(max(set(vals), key=lambda v: (vals.count(v), -vals.index(v))))
        out.append(row)
    return out

from collections import Counter, deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [row[:] for row in grid]
    seen = set()
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r,c) in seen:
                continue
            q=deque([(r,c)]); seen.add((r,c)); comp=[]
            while q:
                y,x=q.popleft(); comp.append((y,x))
                for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx] != bg:
                        seen.add((yy,xx)); q.append((yy,xx))
            counts=Counter(grid[y][x] for y,x in comp)
            color,n=counts.most_common(1)[0]
            y0=min(y for y,x in comp); y1=max(y for y,x in comp)
            x0=min(x for y,x in comp); x1=max(x for y,x in comp)
            area=(y1-y0+1)*(x1-x0+1)
            # A coherent colored block with sparse marker contamination: restore its rectangle.
            if len(comp)>=4 and n/area >= 0.55:
                for y in range(y0,y1+1):
                    for x in range(x0,x1+1): out[y][x]=color
            else:
                # isolated specks are noise/markers
                for y,x in comp: out[y][x]=bg
    return out

