from collections import deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    # The most common color is the canvas. Retain coherent rectangular color
    # blocks; isolated/interior marker colors are removed or repaired.
    freq = {}
    for row in grid:
        for v in row: freq[v] = freq.get(v, 0) + 1
    bg = max(freq, key=freq.get)
    out = [[bg] * w for _ in range(h)]
    for color in freq:
        if color == bg: continue
        seen = set()
        for r in range(h):
            for c in range(w):
                if grid[r][c] != color or (r,c) in seen: continue
                q=deque([(r,c)]); seen.add((r,c)); cells=[]
                while q:
                    y,x=q.popleft(); cells.append((y,x))
                    for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                        if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==color:
                            seen.add((yy,xx)); q.append((yy,xx))
                y0=min(y for y,x in cells); y1=max(y for y,x in cells)
                x0=min(x for y,x in cells); x1=max(x for y,x in cells)
                area=(y1-y0+1)*(x1-x0+1)
                if area >= 4 and len(cells)/area >= 0.60:
                    for y in range(y0,y1+1):
                        for x in range(x0,x1+1): out[y][x]=color
    return out

