from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    # Remove singleton noise and repair isolated holes in monochromatic blobs.
    out = [row[:] for row in grid]
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            neigh = [grid[y][x] for y in range(max(0,r-1),min(h,r+2))
                     for x in range(max(0,c-1),min(w,c+2)) if (y,x)!=(r,c)]
            nonbg = Counter(x for x in neigh if x != bg)
            if v != bg and not nonbg and v not in neigh:
                out[r][c] = bg
            elif nonbg:
                color, count = nonbg.most_common(1)[0]
                if count >= 3 and (v == bg or v != color):
                    out[r][c] = color
    return out

