from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    # Erase isolated noise and repair isolated wrong-color pixels surrounded
    # by the actual contiguous shape color.
    for r in range(h):
        for c in range(w):
            v = grid[r][c]
            neighbors = [grid[y][x] for y in range(max(0,r-1), min(h,r+2))
                         for x in range(max(0,c-1), min(w,c+2)) if (y,x)!=(r,c)]
            colored = Counter(x for x in neighbors if x != bg)
            if v == bg:
                if colored:
                    color, n = colored.most_common(1)[0]
                    if n >= 3:
                        out[r][c] = color
            elif not colored:
                out[r][c] = bg
            else:
                color, n = colored.most_common(1)[0]
                if n >= 3 and v != color:
                    out[r][c] = color
                elif not any(x == v for x in neighbors):
                    out[r][c] = bg
    return out

