from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    # Identify non-background monochrome regions, then complete rectangular
    # objects where the region is a near-rectangle; isolated overlays vanish.
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == bg or (r,c) in seen:
                continue
            stack=[(r,c)]; seen.add((r,c)); pts=[]
            while stack:
                y,x=stack.pop(); pts.append((y,x))
                for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and grid[yy][xx]==color:
                        seen.add((yy,xx)); stack.append((yy,xx))
            comps.append((color,pts))
    # Reconstruct substantial block components by their bounding rectangles.
    for color, pts in comps:
        if len(pts) < 4:
            continue
        r0=min(y for y,x in pts); r1=max(y for y,x in pts)
        c0=min(x for y,x in pts); c1=max(x for y,x in pts)
        area=(r1-r0+1)*(c1-c0+1)
        if len(pts)/area >= 0.68:
            for y in range(r0,r1+1):
                for x in range(c0,c1+1):
                    out[y][x]=color
    # Remove remaining isolated non-background speckles that are not part of
    # any substantial component.
    for color, pts in comps:
        if len(pts) < 4:
            for y,x in pts:
                out[y][x]=bg
    return out

