from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    out = [row[:] for row in grid]
    # Sparse anomalous marks have low global frequency; remove them.
    # Foreground shapes are repeated colors, sometimes with single-cell holes.
    keep = {v for v, n in counts.items() if v == bg or n >= 4}
    for r in range(h):
        for c in range(w):
            if grid[r][c] not in keep:
                out[r][c] = bg
    # Fill single-cell holes inside a rectangle-like object component.
    seen = set()
    for r in range(h):
        for c in range(w):
            color = out[r][c]
            if color == bg or (r,c) in seen:
                continue
            stack=[(r,c)]; seen.add((r,c)); pts=[]
            while stack:
                y,x=stack.pop(); pts.append((y,x))
                for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0<=yy<h and 0<=xx<w and (yy,xx) not in seen and out[yy][xx]==color:
                        seen.add((yy,xx)); stack.append((yy,xx))
            if len(pts) >= 4:
                r0=min(y for y,x in pts); r1=max(y for y,x in pts)
                c0=min(x for y,x in pts); c1=max(x for y,x in pts)
                area=(r1-r0+1)*(c1-c0+1)
                if len(pts)/area >= 0.75:
                    for y in range(r0,r1+1):
                        for x in range(c0,c1+1):
                            out[y][x]=color
    return out

