def transform(grid):
    # Restore masked cells by continuing each row's five-color horizontal cycle.
    out = [row[:] for row in grid]
    palette = [1, 3, 5, 7, 9]
    for r, row in enumerate(grid):
        known = [c for c, v in enumerate(row) if v in palette]
        if not known:
            continue
        # The large patterned field has a five-cell horizontal period. Find its
        # phase from the nearest reliable nonzero sequence in this row.
        for c, v in enumerate(row):
            if v != 0:
                continue
            candidates = []
            for k in known:
                if abs(k-c) < 5:
                    candidates.append((abs(k-c), (palette.index(grid[r][k]) - (k-c)) % 5))
            if candidates:
                phase = min(candidates)[1]
            else:
                # Phase is constant modulo 5 across each patterned row; use a
                # known cell in the uninterrupted right-hand portion.
                k = min(known, key=lambda x: abs(x-c))
                phase = (palette.index(grid[r][k]) - k) % 5
            out[r][c] = palette[(c + phase) % 5]
    return out

