def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    ones = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 1]
    sixes = [(r, c) for r, row in enumerate(grid) for c, v in enumerate(row) if v == 6]

    # Complete any diagonal segment whose endpoints are both 1 markers.
    for i, (r1, c1) in enumerate(ones):
        for r2, c2 in ones[i + 1:]:
            if abs(r2-r1) == abs(c2-c1):
                dr = 1 if r2 > r1 else -1
                dc = 1 if c2 > c1 else -1
                for k in range(1, abs(r2-r1)):
                    r, c = r1 + dr*k, c1 + dc*k
                    if grid[r][c] not in (1, 6):
                        out[r][c] = 1

    # The 6 markers form full diagonals opposite the 1-marker diagonal.
    # For a descending-right 1 diagonal, extend 6s along descending-left;
    # for descending-left 1 diagonal, use descending-right.
    if len(ones) >= 2 and len(sixes) >= 2:
        # Determine the diagonal family from an aligned pair of 1 markers.
        slope = None
        for i, (r1, c1) in enumerate(ones):
            for r2, c2 in ones[i+1:]:
                if abs(r2-r1) == abs(c2-c1):
                    slope = 1 if (r2-r1)*(c2-c1) > 0 else -1
                    break
            if slope is not None:
                break
        if slope is not None:
            dc = -1 if slope == 1 else 1
            for sr, sc in sixes:
                r, c = sr, sc
                while 0 <= r-1 < h and 0 <= c-dc < w:
                    r -= 1
                    c -= dc
                while 0 <= r < h and 0 <= c < w:
                    if grid[r][c] not in (1, 6):
                        out[r][c] = 6
                    r += 1
                    c += dc
    return out

