def transform(grid):
    h,w=len(grid),len(grid[0])
    out=[row[:] for row in grid]
    # Color 9 (or equivalent sparse interior marker) extends toward the right.
    from collections import Counter
    counts=Counter(v for row in grid for v in row)
    bg=counts.most_common(1)[0][0]
    edge=[v for line in (grid[0],grid[-1],[grid[r][0] for r in range(h)],[grid[r][-1] for r in range(h)]) for v in line if v!=bg]
    bar=Counter(edge).most_common(1)[0][0]
    marker=min((v for v in counts if v not in (bg,bar)),key=lambda v:counts[v])
    for r in range(h):
        for c in range(w):
            if grid[r][c]==marker:
                out[r][c]=4
                for cc in range(c+1,w):
                    if grid[r][cc]==bg:
                        out[r][cc]=marker
    return out

