from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    out = [row[:] for row in grid]
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    border = [v for line in (grid[0], grid[-1], [grid[r][0] for r in range(h)], [grid[r][-1] for r in range(h)]) for v in line if v != bg]
    rail = Counter(border).most_common(1)[0][0]
    marker = min((v for v in counts if v not in (bg, rail)), key=lambda v: counts[v])
    for edge_row, step in ((0, 1), (h - 1, -1)):
        cols = [c for c, value in enumerate(grid[edge_row]) if value == rail]
        if cols:
            for c in set((cols[0], cols[-1])):
                r = edge_row + step
                while 0 <= r < h:
                    if grid[r][c] == marker:
                        out[r][c] = 4
                        break
                    if grid[r][c] == bg:
                        out[r][c] = marker
                    r += step
    return out

