    h,w=len(grid),len(grid[0]); out=[row[:] for row in grid]
    pts=[(r,c) for r in range(h) for c in range(w) if grid[r][c]==9]
    for r,c in pts:
        out[r][c]=4
        for dr,dc in ((-1,-1),(1,1)):
            rr,cc=r+dr,c+dc
            while 0<=rr<h and 0<=cc<w:
                if grid[rr][cc]==3: out[rr][cc]=9
                rr+=dr;cc+=dc
    return out

