    for r,c in markers:
        out[r][c]=4
        for dr,dc in ((1,0),(-1,0),(0,1),(0,-1)):
            rr,cc=r+dr,c+dc
            while 0<=rr<h and 0<=cc<w:
                if grid[rr][cc]==9:
                    out[rr][cc]=4
                    break
                if grid[rr][cc]==3:
                    out[rr][cc]=9
                rr+=dr
                cc+=dc
    return out

