def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    bg = grid[0][0]
    rails = [(r,c) for r in range(h) for c in range(w) if grid[r][c] == 2]
    marks = [(r,c) for r in range(h) for c in range(w) if grid[r][c] not in (bg,2)]
    if not rails or not marks:
        return out
    # Each foreground seed projects a one-cell-wide line away from the rail.
    # The object stays intact; color 8 marks the projected continuation.
    rail_rows = sorted({r for r,c in rails})
    rail_cols = sorted({c for r,c in rails})
    horizontal = len(rail_cols) > len(rail_rows)
    if horizontal:
        rail = rail_rows[0]
        for r,c in marks:
            if r > rail:
                for rr in range(r+1,h):
                    if grid[rr][c] == bg:
                        out[rr][c] = 8
            elif r < rail:
                for rr in range(r-1,-1,-1):
                    if grid[rr][c] == bg:
                        out[rr][c] = 8
    else:
        rail = rail_cols[0]
        for r,c in marks:
            if c < rail:
                for cc in range(c-1,-1,-1):
                    if grid[r][cc] == bg:
                        out[r][cc] = 8
            elif c > rail:
                for cc in range(c+1,w):
                    if grid[r][cc] == bg:
                        out[r][cc] = 8
    return out

