def transform(grid):
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    bg = grid[0][0]
    rail_cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == 2]
    if not rail_cells:
        return out
    rail_rows = {r for r, c in rail_cells}
    rail_cols = {c for r, c in rail_cells}
    horizontal = len(rail_cols) > len(rail_rows)
    pts = [(r, c) for r in range(h) for c in range(w) if grid[r][c] not in (bg, 2)]
    if not pts:
        return out
    top, bottom = min(r for r, c in pts), max(r for r, c in pts)
    left, right = min(c for r, c in pts), max(c for r, c in pts)
    if horizontal:
        rail = min(rail_rows)
        if bottom < rail:
            # Motif already lies above rail: leave it and draw separator behind it.
            row = top - 1
            if 0 <= row < h:
                out[row] = [8 if v == bg else v for v in out[row]]
        else:
            # Move motif to the rail's lower side, adjacent; stripe on its far edge.
            dr = rail + 1 - top
            for r, c in pts:
                rr = r + dr
                out[rr][c] = grid[r][c]
            stripe = rail + 1 + (bottom - top) + 1
            if stripe < h:
                out[stripe] = [8 if v == bg else v for v in out[stripe]]
    else:
        rail = min(rail_cols)
        if left > rail:
            dc = rail + 1 - left
            for r, c in pts:
                out[r][c + dc] = grid[r][c]
            stripe = rail + 1 + (right - left) + 1
            if stripe < w:
                for r in range(h):
                    if grid[r][stripe] == bg:
                        out[r][stripe] = 8
        else:
            dc = rail - 1 - right
            for r, c in pts:
                out[r][c + dc] = grid[r][c]
            stripe = rail - 2 - (right - left)
