def transform(grid):
    """Copy the marker shape to every exact all-zero translated placement."""
    h, w = len(grid), len(grid[0])
    marker_colors = {v for row in grid for v in row if v not in (0,)}
    # The marker is the smallest connected component among nonzero colors;
    # components belonging to the noisy background are large and scattered.
    from collections import deque
    components = []
    seen = set()
    for r in range(h):
        for c in range(w):
            color = grid[r][c]
            if color == 0 or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                x, y = q.popleft()
                comp.append((x, y))
                for dx, dy in ((1,0),(-1,0),(0,1),(0,-1)):
                    nx, ny = x+dx, y+dy
                    if 0 <= nx < h and 0 <= ny < w and grid[nx][ny] == color and (nx,ny) not in seen:
                        seen.add((nx,ny)); q.append((nx,ny))
            components.append((color, comp))
    color, comp = min(components, key=lambda z: len(z[1]))
    # Use the marker component's exact coordinates as a stencil.
    out = [row[:] for row in grid]
    minr, minc = min(r for r,c in comp), min(c for r,c in comp)
    stencil = [(r-minr, c-minc) for r,c in comp]
    for ar in range(h):
        for ac in range(w):
            if (ar, ac) == (minr, minc):
                continue
            cells = [(ar+dr, ac+dc) for dr,dc in stencil]
            if all(0 <= r < h and 0 <= c < w and grid[r][c] == 0 for r,c in cells):
                for r,c in cells:
                    out[r][c] = color
    return out

