def transform(grid):
    g = [row[:] for row in grid]
    h, w = len(g), len(g[0])
    # The 2x2 marker selects the color that replaces background in all
    # occurrences of its 2x2 pattern elsewhere; preserve the marker itself.
    marker = [(r, c) for r in range(h) for c in range(w)
              if g[r][c] not in (0, 3, 5, 7)]
    if not marker:
        return g
    mark_color = g[marker[0][0]][marker[0][1]]
    # Marker in these tasks is a connected group; template is its bounding mask.
    r0, r1 = min(r for r, c in marker), max(r for r, c in marker)
    c0, c1 = min(c for r, c in marker), max(c for r, c in marker)
    shape = {(r-r0, c-c0) for r, c in marker}
    src_color = next((g[r][c] for r, c in marker if g[r][c] != mark_color), None)
    # If marker uses a single distinct color, background cells are the target;
    # determine the pattern's non-marker fill color from surrounding grid.
    if src_color is None:
        counts = {}
        for row in g:
            for x in row:
                if x != mark_color:
                    counts[x] = counts.get(x, 0) + 1
        src_color = max(counts, key=counts.get)
    out = [row[:] for row in g]
    for r in range(h):
        for c in range(w):
            coords = [(r+dr, c+dc) for dr, dc in shape]
            if not all(0 <= rr < h and 0 <= cc < w for rr, cc in coords):
                continue
            if all(g[rr][cc] == src_color for rr, cc in coords):
                for rr, cc in coords:
                    # Do not overwrite the embedded marker.
                    if g[rr][cc] != mark_color:
                        out[rr][cc] = mark_color
    return out

